import sys; sys.path.insert(0,'/tmp/explore/multi'); sys.path.insert(0,'/tmp/h')
from mh2 import *
from dnsbuild import *
import threading
L=threading.Lock(); CNT=[0]
def ok(q,n,sn=1):
    return hdr(an=1)+q['qbytes']+rr(q['qname'],1,q['qclass'],n, bytes([sn,0,0,n]))

def mkresp(failidx, mode):
    def resp(req,i,srv,port):
        q=parse_q(req)
        with L:
            CNT[0]+=1; n=CNT[0]
        if i==failidx:
            if mode=='none': return None
            if mode=='garbage': return b'\x00\x00nonsense-not-dns'
            if mode=='nxdomain': return hdr(flags=0x8183,an=0)+q['qbytes']
            if mode=='servfail': return hdr(flags=0x8182,an=0)+q['qbytes']
            if mode=='refused': return hdr(flags=0x8185,an=0)+q['qbytes']
            if mode=='trunc': return hdr(flags=0x8380,an=0)+q['qbytes']
        return ok(q,n)
    return resp

def go(title,args,ns,counts,failidx,mode,**kw):
    CNT[0]=0
    r=runmulti(args,mkresp(failidx,mode),ns,counts,**kw)
    dump(title,r)

for mode in ['nxdomain','servfail','refused']:
    go('3 domains, #2 (index1) = %s'%mode,['a.example','b.example','c.example','-n','127.0.0.1:@PORT@'],1,[3],1,mode)
for mode in ['nxdomain','servfail']:
    go('3 domains, #1 (index0) = %s'%mode,['a.example','b.example','c.example','-n','127.0.0.1:@PORT@'],1,[3],0,mode)
EOF
